CREATE TABLE devices (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, allowed_workspace_ids TEXT NOT NULL, revoked_at_ms INTEGER, created_at_ms INTEGER NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, time_zone TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, default_platforms TEXT NOT NULL, service_profile_id TEXT NOT NULL, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL);
CREATE TABLE connections (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), provider TEXT NOT NULL CHECK(provider IN ('meta','buffer')), label TEXT NOT NULL, secret_cipher TEXT NOT NULL, key_version INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, updated_at_ms INTEGER NOT NULL, UNIQUE(id,workspace_id));
CREATE TABLE channels (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), connection_id TEXT NOT NULL, remote_id TEXT NOT NULL, platform TEXT NOT NULL, provider TEXT NOT NULL, ready INTEGER NOT NULL DEFAULT 0, limits_json TEXT NOT NULL, discovered_at_ms INTEGER NOT NULL, UNIQUE(id,workspace_id), FOREIGN KEY(connection_id,workspace_id) REFERENCES connections(id,workspace_id));
CREATE TABLE posts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), draft_id TEXT NOT NULL, revision INTEGER NOT NULL, plan_hash TEXT NOT NULL, plan_json TEXT NOT NULL, state TEXT NOT NULL, due_at_ms INTEGER, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL, workflow_id TEXT, locked_at_ms INTEGER, UNIQUE(workspace_id,draft_id,revision), UNIQUE(id,workspace_id));
CREATE INDEX posts_workspace_due ON posts(workspace_id,state,due_at_ms);
CREATE INDEX posts_pending ON posts(state,updated_at_ms);
CREATE TABLE targets (post_id TEXT NOT NULL, revision INTEGER NOT NULL, channel_id TEXT NOT NULL, workspace_id TEXT NOT NULL, state TEXT NOT NULL, claim_id TEXT, claimed_at_ms INTEGER, remote_id TEXT, public_url TEXT, error_json TEXT, next_check_ms INTEGER, updated_at_ms INTEGER NOT NULL, PRIMARY KEY(post_id,revision,channel_id), FOREIGN KEY(post_id,workspace_id) REFERENCES posts(id,workspace_id), FOREIGN KEY(channel_id,workspace_id) REFERENCES channels(id,workspace_id));
CREATE INDEX targets_due ON targets(state,next_check_ms);
CREATE TABLE target_parts (post_id TEXT NOT NULL, revision INTEGER NOT NULL, channel_id TEXT NOT NULL, part_index INTEGER NOT NULL CHECK(part_index>=0), state TEXT NOT NULL, remote_id TEXT, public_url TEXT, error_json TEXT, PRIMARY KEY(post_id,revision,channel_id,part_index), FOREIGN KEY(post_id,revision,channel_id) REFERENCES targets(post_id,revision,channel_id));
CREATE TABLE assets (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), source_asset_id TEXT NOT NULL, recipe_id TEXT, object_key TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('image','video')), mime_type TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), sha256 TEXT, width INTEGER, height INTEGER, duration_ms INTEGER, state TEXT NOT NULL, multipart_id TEXT, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL, delete_after_ms INTEGER, UNIQUE(id,workspace_id));
CREATE INDEX assets_cleanup ON assets(state,delete_after_ms);
CREATE INDEX assets_content ON assets(workspace_id,sha256,state);
CREATE TABLE asset_uses (asset_id TEXT NOT NULL, workspace_id TEXT NOT NULL, post_id TEXT NOT NULL, revision INTEGER NOT NULL, channel_id TEXT NOT NULL, alias_nonce TEXT NOT NULL UNIQUE, sent_name TEXT NOT NULL, consumed_at_ms INTEGER, PRIMARY KEY(asset_id,post_id,revision,channel_id), FOREIGN KEY(asset_id,workspace_id) REFERENCES assets(id,workspace_id), FOREIGN KEY(post_id,workspace_id) REFERENCES posts(id,workspace_id), FOREIGN KEY(post_id,revision,channel_id) REFERENCES targets(post_id,revision,channel_id));
CREATE TABLE upload_reservations (asset_id TEXT PRIMARY KEY REFERENCES assets(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), bytes INTEGER NOT NULL CHECK(bytes>0), expires_at_ms INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','completed','released')));
CREATE INDEX reservations_expiry ON upload_reservations(state,expires_at_ms);
CREATE TABLE rate_budgets (connection_id TEXT NOT NULL REFERENCES connections(id), window_seconds INTEGER NOT NULL, remaining INTEGER NOT NULL CHECK(remaining>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0), reset_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL, PRIMARY KEY(connection_id,window_seconds));
CREATE TABLE dispatch_outbox (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), revision INTEGER NOT NULL, workflow_id TEXT NOT NULL UNIQUE, action TEXT NOT NULL CHECK(action IN ('create','terminate')), state TEXT NOT NULL, next_attempt_ms INTEGER NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, error_code TEXT, UNIQUE(post_id,revision,action));
CREATE INDEX dispatch_due ON dispatch_outbox(state,next_attempt_ms);
CREATE TABLE report_outbox (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), dedupe_key TEXT NOT NULL, kind TEXT NOT NULL, text_ar TEXT NOT NULL, state TEXT NOT NULL, remote_message_id TEXT, claim_id TEXT, claimed_at_ms INTEGER, next_attempt_ms INTEGER, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL, UNIQUE(workspace_id,dedupe_key));
CREATE INDEX reports_due ON report_outbox(state,next_attempt_ms);
CREATE TABLE service_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at_ms INTEGER NOT NULL);
